__NUXT_JSONP__("/ch/stay", (function(a,b,c,d,e,f,g,h,i,j){return {data:[{details:{slug:"ch",pageTitle:"住宿 | Mentor Language Institute",pageDescription:"MLI与USSS合作，为MLI的学生提供住宿信息",title:"住宿",subtitle:["MLI与USSS合作，为MLI的学生提供住宿信息 \u003Cbr \u002F\u003E有关更多详细信息，请访问  \u003Ca href=\"www.usssinc.net\u002Fch\" target=\"_blank\"\u003Ewww.usssinc.net\u002Fch\u003C\u002Fa\u003E"],image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:"学生可选择寄宿或是宿舍",types:[{title:"宿舍",description:["我们共有40多间宿舍，每间宿舍都有来自各个国家的学生。因此学生有很多交流的机会。如果学生的预算有限，我们建议您选择宿舍。"],lists:["\u003Cb\u003E宿舍类型\u003C\u002Fb\u003E : 单人间 (一人), 双人间 (两人) 和 四人间 (四人)","\u003Cb\u003E供餐\u003C\u002Fb\u003E ：不提供早\u002F中\u002F晚餐【配套齐全的厨房设施】","\u003Cb\u003E个人隐私\u003C\u002Fb\u003E ：宿舍和寄宿家庭同样注重隐私。由于宿舍学生较多，因此，我们更加注重隐私保护。","\u003Cb\u003E交通\u003C\u002Fb\u003E ：公车大约20分钟，步行大约40分钟。"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"宿舍费用",table:{tableMaxCol:4,title:"安置费用* : $200\u003Cbr \u002F\u003E 如果小于18岁，租金将比18岁以上的人的价格高出大约10%。",thead:[b,c,"合住 (两人)","四人间 (四人)"],tbody:[[d,a,a,a],[e,"$550","$410",a],[f,"$1,100","$820","$600"],[g,"$1,650","$1,230","$900"],[h,"$2,200","$1,640","$1,200"],[i,"$4,160","$2,960","$2,160"],[j,"$6,240","$4,440","$3,240"]]},notes:["*安置费用需一次性缴交。不可退还。\u003Cbr \u002F\u003E**押金将在学生搬出后退还。\u003Cbr \u002F\u003E"]}]},{title:"寄宿家庭",description:["寄宿家庭适合一些想住在安全且有家庭气息的地方的学生。同时也是一个可以学习美国文化、传统及家庭观念的机会。"],lists:["\u003Cb\u003E宿舍类型 \u003C\u002Fb\u003E ：私人（個人）","\u003Cb\u003E供餐\u003C\u002Fb\u003E ：一日两餐（早餐和晚餐）","\u003Cb\u003E隐私\u003C\u002Fb\u003E ：因家庭而异","\u003Cb\u003E交通\u003C\u002Fb\u003E ：因家庭的地理位置而已"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"寄宿家庭的费用",table:{tableMaxCol:3,title:"安置费用* : $300\u003Cbr \u002F\u003E 如果小于18岁，租金将比18岁以上的人的价格高出大约10%。",thead:[b,c,"合住***"],tbody:[[d,a,a],[e,"$436","$384"],[f,"$872","$768"],[g,"$1,308","$1,152"],[h,"$1,744","$1,536"],[i,"$3,160","$2,904"],[j,"$4,740","$4,356"]]},notes:["*安置费用需一次性缴交，不可退还。\u003Cbr \u002F\u003E**押金将在学生搬出后退还。\u003Cbr \u002F\u003E***您如果申请寄宿家庭的合住房间，您需要和另一个人一起申请。\u003Cbr \u002F\u003E"]}]}],comments:{title:"注意事项",description:["当您刚到达美国时，很难找到安全且信赖的地点，尤其是没有社安号码(SSN)的国际学生。\u003Cbr \u002F\u003E大多数的地方需要SSN及信用历史才能租房。\u003Cbr \u002F\u003E因此，我们建议可以先选择我们的宿舍。","※您的住宿将由 U.S. Support Service Inc.或是其它仲介提供。"]},dir:"\u002Fstay",path:"\u002Fstay\u002Fch",extension:".json",createdAt:"2026-10-22T16:31:31.067Z",updatedAt:"2025-05-26T12:06:27.918Z"}}],fetch:{},mutations:void 0}}("$300","","单间 (一人)","\u003Cb\u003E押金**\u003C\u002Fb\u003E","1 week","2 weeks","3 weeks","4 weeks","8 weeks","12 weeks")));